def is_balanced(s):
    stack = []
    brackets = {'(': ')', '[': ']', '{': '}'}

    for char in s:
        if char in brackets:
            stack.append(char)
        elif char in brackets.values():
            if not stack:
                return False
            top = stack.pop()
            if brackets[top] != char:
                return False
    return not stack
```

